module csr_file (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [7:0]  addr,
    input  logic        wr_en,
    input  logic [31:0] wdata,
    input  logic        rd_en,
    output logic [31:0] rdata,
    output logic [31:0] ctrl_out,
    output logic [31:0] data_out,
    input  logic [31:0] status_in
);

    logic [31:0] ctrl_reg;
    logic [31:0] data_reg;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ctrl_reg <= 32'h0;
            data_reg <= 32'h0;
            rdata    <= 32'h0;
        end else begin
            if (wr_en) begin
                case (addr)
                    8'h00: ctrl_reg <= wdata;
                    8'h08: data_reg <= wdata;
                    default: ;
                endcase
            end
            if (rd_en) begin
                case (addr)
                    8'h00:   rdata <= ctrl_reg;
                    8'h04:   rdata <= status_in;
                    8'h08:   rdata <= data_reg;
                    default: rdata <= 32'h0;
                endcase
            end
        end
    end

    assign ctrl_out = ctrl_reg;
    assign data_out = data_reg;

endmodule
